  if [[ -n "$HEALTH" ]] && printf '%s' "$HEALTH" | python3 -c 'import sys,json; h=json.load(sys.stdin); raise SystemExit(0 if h.get("ok") is True and h.get("version")=="NOVA-2.4.22" else 1)' 2>/dev/null; then break; fi
